import java.awt.*;import java.awt.image.*;import java.io.*;import java.util.*;import javax.imageio.ImageIO;import com.koios.client.arpg.WorldBackdrop;import com.koios.client.graphic.DrawingArea;
/** Scene-only clear respects active clip, keeps other buffers intact and allocates nothing per steady frame. */
public final class WorldBackdropCheck {
 static int checks;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{
 int[] untouched=new int[100];Arrays.fill(untouched,0xAABBCC);int[] sizes={334,503,720,1080};Set<Integer> styles=new HashSet<>();for(WorldBackdrop.Theme theme:WorldBackdrop.Theme.values()){for(int height:sizes){int width=height==334?512:height==503?765:height==720?1280:1920;int[] pixels=new int[width*height];Arrays.fill(pixels,0x79415C);DrawingArea.initDrawingArea(height,width,pixels);DrawingArea.setDrawingArea(height-13,17,width-19,11);int top=DrawingArea.topY,bottom=DrawingArea.bottomY,left=DrawingArea.topX,right=DrawingArea.bottomX;WorldBackdrop.draw(theme);for(int y=0;y<height;y++)for(int x=0;x<width;x++){boolean inside=x>=left&&x<right&&y>=top&&y<bottom;check(inside?pixels[x+y*width]!=0&&pixels[x+y*width]!=0x79415C:pixels[x+y*width]==0x79415C,"Only active world clip painted");}int previous=-1;for(int y=top;y<bottom;y++){int color=pixels[left+y*width];check(previous<0||(color&255)>=(previous&255),"Smooth non-darkening backdrop rows");previous=color;}if(height==334)check(styles.add(pixels[left+height/2*width]),"Biome gradient material distinct");} }
 for(int color:untouched)check(color==0xAABBCC,"Unbound cached UI buffer unchanged");int[] pixels=new int[512*334];DrawingArea.initDrawingArea(334,512,pixels);WorldBackdrop.draw(WorldBackdrop.Theme.BASE);for(int i=0;i<100;i++)WorldBackdrop.draw(WorldBackdrop.Theme.BASE);java.lang.management.ThreadMXBean base=java.lang.management.ManagementFactory.getThreadMXBean();if(base instanceof com.sun.management.ThreadMXBean){com.sun.management.ThreadMXBean bean=(com.sun.management.ThreadMXBean)base;if(bean.isThreadAllocatedMemorySupported()){bean.setThreadAllocatedMemoryEnabled(true);long id=Thread.currentThread().getId(),before=bean.getThreadAllocatedBytes(id);for(int i=0;i<100;i++)WorldBackdrop.draw(WorldBackdrop.Theme.BASE);long allocated=bean.getThreadAllocatedBytes(id)-before;check(allocated<2048,"No per-frame allocations after warmup: "+allocated);System.out.println("Steady100frame allocations: "+allocated+"bytes");}}
 BufferedImage preview=new BufferedImage(1024,668,BufferedImage.TYPE_INT_RGB);Graphics2D g=preview.createGraphics();g.setFont(new Font("SansSerif",0,14));int index=0;for(WorldBackdrop.Theme theme:WorldBackdrop.Theme.values()){BufferedImage image=new BufferedImage(512,334,BufferedImage.TYPE_INT_RGB);DrawingArea.initDrawingArea(334,512,((DataBufferInt)image.getRaster().getDataBuffer()).getData());WorldBackdrop.draw(theme);g.drawImage(image,index%2*512,index/2*334,null);g.setColor(new Color(0xD9CFBA));g.drawString(theme+" / scene clear only",index%2*512+14,index/2*334+25);index++;}g.dispose();ImageIO.write(preview,"png",new File("build/world-backdrop-palettes.png"));System.out.println("Passed "+checks+" backdrop clip/pixel/allocation checks. Actual terrain edge/camera appearance needs live scene QA.");
 }
}
